const crypto = require("crypto");
const dispatch = $("Receive Dispatch Payload").first().json.body;
const geminiRes = $input.first().json || {};
const usageMeta = geminiRes.usageMetadata || {};
const providerMetadata = {
  provider: "gemini",
  model: geminiRes.modelVersion || "gemini-2.5-flash",
  input_tokens: Number(usageMeta.promptTokenCount || 0),
  output_tokens: Number(usageMeta.candidatesTokenCount || 0),
  estimated_cost_minor_units: 0,
  duration_ms: 0
};
let payload;
try {
  const rawText = geminiRes?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (typeof rawText !== "string" || !rawText.trim()) {
    throw new Error("Empty Gemini response text");
  }
  const parsedResult = JSON.parse(rawText);
  if (!parsedResult || typeof parsedResult !== "object" || Array.isArray(parsedResult)) {
    throw new Error("Gemini output must be a JSON object");
  }
  payload = {
    job_id: dispatch.job_id,
    workflow_key: dispatch.workflow_key,
    workflow_version: dispatch.workflow_version,
    document_type: dispatch.document_type,
    event_type: "completed",
    external_execution_id: $execution.id,
    result: parsedResult,
    provider_metadata: providerMetadata
  };
} catch (_err) {
  payload = {
    job_id: dispatch.job_id,
    workflow_key: dispatch.workflow_key,
    workflow_version: dispatch.workflow_version,
    document_type: dispatch.document_type,
    event_type: "failed",
    external_execution_id: $execution.id,
    error_code: "OUTPUT_SCHEMA_INVALID",
    safe_error_message: "Keluaran penyedia AI tidak valid atau gagal diurai.",
    provider_metadata: providerMetadata
  };
}
const rawBody = JSON.stringify(payload);
const ts = Math.floor(Date.now() / 1000);
const eventId = `n8n-cb-${crypto.randomUUID()}`;
const path = dispatch.callback_endpoint;
const canonical = `${ts}.${eventId}.POST.${path}.${rawBody}`;
const sig = crypto.createHmac("sha256", process.env.INTERNAL_HMAC_SECRET || "").update(canonical).digest("hex");
return [{ json: { path, rawBody, ts, eventId, sig } }];

const crypto = require("crypto");
const dispatch = $("Receive Dispatch Payload").first().json.body;
const errItem = $input.first()?.json || {};
const statusCode = Number(errItem?.error?.status || errItem?.statusCode || 0);
const errMsg = String(errItem?.error?.message || errItem?.message || "").toLowerCase();
let errorCode = "AI_PROVIDER_ERROR";
let safeMessage = "Pemrosesan workflow AI mengalami kegagalan.";
if (dispatch.document_type !== "meeting_minutes") {
  errorCode = "UNSUPPORTED_DOCUMENT_TYPE";
  safeMessage = "Tipe dokumen belum didukung pada workflow n8n ini.";
} else if (statusCode === 429) {
  errorCode = "AI_PROVIDER_RATE_LIMIT";
  safeMessage = "Batas laju permintaan penyedia AI tercapai.";
} else if (errMsg.includes("timeout") || errMsg.includes("timed out") || statusCode === 408 || statusCode === 504) {
  errorCode = "AI_PROVIDER_TIMEOUT";
  safeMessage = "Permintaan ke layanan internal atau penyedia AI melebihi batas waktu.";
} else if (statusCode === 404 || statusCode === 409 || statusCode === 410) {
  errorCode = "INVALID_INPUT";
  safeMessage = "Bundel sumber dokumen tidak tersedia atau tidak lagi valid.";
}
const payload = {
  job_id: dispatch.job_id,
  workflow_key: dispatch.workflow_key,
  workflow_version: dispatch.workflow_version,
  document_type: dispatch.document_type,
  event_type: "failed",
  external_execution_id: $execution.id,
  error_code: errorCode,
  safe_error_message: safeMessage
};
const rawBody = JSON.stringify(payload);
const ts = Math.floor(Date.now() / 1000);
const eventId = `n8n-fail-${crypto.randomUUID()}`;
const path = dispatch.callback_endpoint;
const canonical = `${ts}.${eventId}.POST.${path}.${rawBody}`;
const sig = crypto.createHmac("sha256", process.env.INTERNAL_HMAC_SECRET || "").update(canonical).digest("hex");
return [{ json: { path, rawBody, ts, eventId, sig } }];
